mapper.select:
SELECT uid AS userId,user_name,real_name,mobile FROM sys_user_info WHERE delete_state=1
AND user_name ILIKE concat('%',#{params.searchKeyword}::text,'%') OR real_name ILIKE concat('%',#{params.searchKeyword}::text,'%')
AND sui.user_type = #{params.userType}

SELECT uid, user_name, real_name, mobile, user_state, last_login_time, head_icon, last_login_ip, login_count, user_account, create_time, update_time, email FROM sys_user_info sui WHERE delete_state=1 AND user_account not in ('admin')
AND sui.user_state=#{params.state}
AND sui.${params.searchType} ILIKE concat('%',#{params.searchKeyword}::text,'%')
AND last_login_time >=#{params.startTime}
AND last_login_time <=#{params.endTime}
AND sui.user_type = #{params.userType}
AND uid in (SELECT sru.user_id FROM sys_role_user sru WHERE sru.role_id in
#{roleId}
)
ORDER BY update_time DESC

SELECT sui.uid AS userId,sui.user_name,sui.real_name,sui.mobile, COALESCE((SELECT 1 FROM sys_role_user sru where sru.user_id=sui.uid AND sru.role_id=#{params.flagId} limit 1),0) AS flagState FROM sys_user_info sui WHERE sui.delete_state=1
AND sui.user_name ILIKE concat('%',#{params.searchKeyword}::text,'%') OR sui.real_name ILIKE concat('%',#{params.searchKeyword}::text,'%')
AND sui.user_type = #{params.userType}

SELECT sui.uid AS userId,sui.user_name,sui.real_name,sui.mobile, COALESCE((SELECT 1 FROM sys_post_user spu where spu.user_id=sui.uid AND spu.post_id=#{params.flagId} limit 1),0) AS flagState FROM sys_user_info sui WHERE sui.delete_state=1
AND sui.user_name ILIKE concat('%',#{params.searchKeyword}::text,'%') OR sui.real_name ILIKE concat('%',#{params.searchKeyword}::text,'%')
AND sui.user_type = #{params.userType}

SELECT sui.uid AS userId,sui.user_name,sui.real_name,sui.mobile, COALESCE((SELECT 1 FROM sys_department_user sdu where sdu.user_id=sui.uid AND sdu.department_id=#{params.flagId} limit 1),0) AS flagState FROM sys_user_info sui WHERE sui.delete_state=1
AND sui.user_name ILIKE concat('%',#{params.searchKeyword}::text,'%') OR sui.real_name ILIKE concat('%',#{params.searchKeyword}::text,'%')
AND sui.user_type = #{params.userType}

SELECT sui.uid, sui.user_name, sui.real_name, sui.mobile, sui.user_state, sui.last_login_time, sui.delete_state, sui.last_login_ip, sui.login_count, sui.create_time, sui.update_time, sui.user_account, sui.password, sui.salt, sui.email, sui.head_icon, sui.code, sui.sync_kingdee_id from sys_user_info sui LEFT JOIN sys_department_user sdu on sui.uid = sdu.user_id where sui.user_type = 'erp'
and sdu.department_id in
#{id}

WITH RECURSIVE T ( ID, NAME, parent_id, PATH ) AS (
SELECT ID,NAME,PARENT_ID,ID::text AS PATH FROM sys_department
WHERE name = #{deptName}
UNION ALL
SELECT st.ID,st.NAME,st.PARENT_ID,T.PATH ||','|| st.ID
FROM sys_department st JOIN T ON st.PARENT_ID = T.ID
)
SELECT ID,NAME,PARENT_ID,PATH FROM T ORDER BY 	PATH;

select sui.uid as userId, sui.user_name as userName, sui.real_name as realName, sui.user_state as userState, sui.update_user_name as updateUserName, sui.update_time as updateTime, sui.create_time as createTime from sys_user_info sui
${params.sqlMap.default} and sui.delete_state = 1 and sui.user_type = 'erp'
and sui.user_name ilike concat('%',#{params.userName}::text,'%')
and sui.real_name ilike concat('%',#{params.realName}::text,'%')
and sui.user_state = #{params.userState}
and sui.uid in
#{item}
and sui.uid in ( select sru.user_id from sys_role_user sru
sru.role_id in
#{item}
)
and sui.uid in ( select sdu.user_id from sys_department_user sdu
sdu.department_id in
#{item}
)
and sui.update_user_id in
#{item}
and sui.update_time >= #{params.updateTimeList[0]} and (#{params.updateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sui.update_time

SELECT sui.uid, sui.user_name, sui.real_name, sui.mobile, sui.email, sui.is_super AS isSuper, sui.user_state AS userState, CASE WHEN suw.union_id IS NULL THEN false ELSE true END AS isBindWechat, sui.last_login_time, sui.create_user_name, sui.create_time FROM sys_user_info sui LEFT JOIN sys_user_wechat AS suw ON suw.uid = sui.uid
${params.sqlMap.default}
AND delete_state=1 AND user_account not in ('admin')
AND sui.user_type = #{params.userType}
AND sui.is_super = #{params.isSuper}
AND sui.uid in
#{uid}
ORDER BY sui.create_time DESC

SELECT sui.uid, sui.user_name, sui.real_name, sui.mobile, sui.email, sui.is_super, sui.user_state AS userState, CASE WHEN suw.union_id IS NULL THEN false ELSE true END AS isBindWechat, sui.last_login_time, sui.create_user_name, sui.create_time FROM sys_user_info sui LEFT JOIN sys_user_wechat AS suw ON suw.uid = sui.uid
${params.sqlMap.default}
AND delete_state=1 AND user_account not in ('admin')
AND sui.user_type = #{params.userType}
AND sui.is_super = #{params.isSuper}
AND sui.uid in
#{uid}
ORDER BY sui.create_time DESC
